fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // Check if each pile has enough cookies for the special guests (m)
    if a < m || b < m {
        return false;
    }

    // Total cookies required = 
    // regular guests (n) each need 1 cookie,
    // special guests (m) each need 2 cookies (one from each pile)
    let total_required = n + 2 * m;

    // Check if total cookies available across both piles is enough
    (a as u16 + b as u16) >= total_required as u16
}